prev=""
while true; do
  s=$(gh pr checks 57 --json name,bucket 2>/dev/null) || { sleep 30; continue; }
  [ -z "$s" ] && { sleep 30; continue; }
  cur=$(jq -r '.[] | select(.bucket!="pending") | "\(.name): \(.bucket)"' <<<"$s" 2>/dev/null | sort)
  comm -13 <(echo "$prev") <(echo "$cur")
  prev=$cur
  jq -e 'length > 0 and all(.bucket!="pending")' <<<"$s" >/dev/null 2>&1 && { echo "ALL CHECKS COMPLETE"; break; }
  sleep 30
done
